import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_UPDATED_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_ZIP4_RE = re.compile(r"[0-9]{5}-[0-9]{4}")
_DIGITS = "0123456789"


def _text(value):
    return "" if value is None else str(value)


def _all_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = _text(raw)
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = f"{local}@gmail.com"
    return s


def _valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = _text(raw).lower()
    cuts = [i for i in (s.find("x"), s.find("ext"), s.find("#")) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    s = _text(raw).strip()
    if _ZIP4_RE.fullmatch(s):
        s = s.split("-", 1)[0]
    if len(s) == 4 and _all_digits(s):
        s = "0" + s
    if len(s) == 5 and _all_digits(s):
        return s
    return ""


def _normalize_name(raw):
    s = _text(raw).strip()
    if s.isupper() or s.islower():
        return s.title()
    return s


_UPDATED_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")


def _parse_updated(raw):
    s = _text(raw).strip()
    for fmt in _UPDATED_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _is_opted_out(raw):
    return _text(raw).strip().lower() in _OPT_OUT_VALUES


def _parse_tags(raw):
    parts = re.split(r"[;,]", _text(raw))
    return {p.strip().lower() for p in parts if p.strip()}


def _sort_date(rec):
    return rec["updated"] if rec["updated"] is not None else datetime.min


def _pick(indices, records, field):
    cands = [i for i in indices if records[i][field]]
    if not cands:
        return ""
    best = max(
        cands,
        key=lambda i: (records[i]["source"] == "manual", _sort_date(records[i]), -i),
    )
    return records[best][field]


def dedupe_contacts(rows):
    # Step 1: normalize rows and drop those with neither a valid email nor a valid phone.
    records = []
    for row in rows:
        email = _normalize_email(row.get("email"))
        if not _valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone"))
        if not email and not phone:
            continue
        records.append({
            "first": _normalize_name(row.get("first_name")),
            "last": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email,
            "phone": phone,
            "source": _text(row.get("source")).strip().lower(),
            "tags": _parse_tags(row.get("tags")),
            "opted_out": _is_opted_out(row.get("opted_out")),
            "updated": _parse_updated(row.get("updated")),
        })

    # Step 2: union-find over match keys (transitive matching).
    n = len(records)
    parent = list(range(n))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    seen = {}
    for i, rec in enumerate(records):
        keys = []
        if rec["email"]:
            keys.append(("email", rec["email"]))
        if rec["phone"] and rec["last"]:
            keys.append(("phone", rec["phone"], rec["last"].casefold()))
        for key in keys:
            if key in seen:
                union(i, seen[key])
            else:
                seen[key] = i

    # Step 3: group rows, ordered by earliest row in the input.
    groups = {}
    order = []
    for i in range(n):
        root = find(i)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(i)

    # Step 4: build one output record per person.
    result = []
    for root in order:
        idx = groups[root]
        all_tags = set()
        for i in idx:
            all_tags |= records[i]["tags"]
        dates = [records[i]["updated"] for i in idx if records[i]["updated"] is not None]
        result.append({
            "first_name": _pick(idx, records, "first"),
            "last_name": _pick(idx, records, "last"),
            "zip": _pick(idx, records, "zip"),
            "email": _pick(idx, records, "email"),
            "phone": _pick(idx, records, "phone"),
            "source": _pick(idx, records, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(records[i]["opted_out"] for i in idx) else "N",
            "updated": max(dates).strftime("%Y-%m-%d") if dates else "",
        })
    return result
```

Notes for the send:

- **Opt-outs:** `opted_out` is set at the person level. If any row for a person is opted out, the output shows `"Y"`. Exclude every person with `opted_out == "Y"` from the send list, not only the rows that opted out.
- **Unparseable `updated` values:** these are treated as the oldest possible date when choosing a row. If your export has formats outside the three in the data person's spec, they will silently lose recency ties, so it's worth spot-checking.
- **Source preference:** `source` follows the same rule as the other fields, so a group with any "manual" row will take its source from a manual row.
